head.script:
scwin.screenId = "jldfil00052";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.upd_attachFile = (typeof __krxFileControl === 'function') ? __krxFileControl('upd_attachFile') : ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelector('[id="upd_attachFile"]');

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil00052.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.btn_ElwExcelUpload_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_ElwExcelUpload_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_ElwExcelUpload_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.elwExcelUpload()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil00052.btn_ElwExcelUpload_onclick' }); }
};

/**
 * @event
 * @name scwin.btn_closePop_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_closePop_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_closePop_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.close_pop()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil00052.btn_closePop_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_ElwExcelUpload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_ElwExcelUpload = async function () {
    const sbmOptions = {
        id: "tx_fn_ElwExcelUpload",
        method: "post",
        action: "/submission/disclosureExl.do?method=excelUpload",
        ref: "dma_ElwExcelUploadReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil00052.tx_fn_ElwExcelUpload" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.elwExcelUpload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.elwExcelUpload = async function () {
    /* sdd-asis-lifecycle:begin fn_ElwExcelUpload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const form = (document.disclosureFrm || { elements: [] });
    if ($c.util.getComponent('upd_attachFile').getValue() == null || ($c.util.getComponent('upd_attachFile').getValue() == null ? '' : String($c.util.getComponent('upd_attachFile').getValue())) === '') {
        return;
    } else {
        if (!scwin.checkFileType($c.util.getComponent('upd_attachFile').getValue())) {
            await $c.win.alert("엑셀 파일만(xls) 업로드 가능합니다.");
            $("#upd_attachFile").replaceWith($("#upd_attachFile").clone(true));
            return;
        }
    }
    if (await $c.win.confirm("업로드 하시겠습니까?")) {
        prgIfm.setStyle("display", "");
        $("#prgIfm").attr("src", "/common/progress_blank_pop.jsp");
        $('.btn_w_gra').bind('click', false);
        form.action = "/submission/disclosureExl.do?method=excelUpload";
        await scwin.tx_fn_ElwExcelUpload();
        (($c.util.getComponent('upd_attachFile')) && ($c.util.getComponent('upd_attachFile')).setDisabled ? ($c.util.getComponent('upd_attachFile')).setDisabled(('disabled') === 'disabled' || ('disabled') === 'readonly' || ('disabled') === 'checked' ? true : ('disabled')) : void 0);
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.checkFileType
 * @author Inswave
 * @date 2026. 09. 29
 * @param filePath
 * @returns
 * @hidden N
*/
scwin.checkFileType = function (filePath) {
    /* sdd-asis-lifecycle:begin checkFileType — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (filePath == null || filePath === "") {
        return false;
    }
    const tfp = filePath.toLowerCase();
    if (tfp.indexOf(".xls") < 0 || tfp.substr(tfp.length - 4, 4) !== ".xls") {
        return false;
    }
    return true;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.close_pop
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.close_pop = async function () {
    /* sdd-asis-lifecycle:begin close_pop — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if ($c.util.getComponent('upd_attachFile').getValue().length > 0) {
        if (await $c.win.confirm("종료 하시겠습니까?")) {
            $c.win.closePopup();
        } else {
            return;
        }
    }
    $c.win.closePopup();
    /* sdd-asis-lifecycle:end */
};
